-- SUPABASE QUICK MIGRATION: CORE RATES, SETTINGS & DISCONTINUE

CREATE TABLE IF NOT EXISTS "company" (
  "id" INTEGER,
  "name" TEXT,
  "address" TEXT,
  "city" TEXT,
  "pincode" TEXT,
  "phone" TEXT,
  "mobile" TEXT,
  "fax" TEXT,
  "email" TEXT
);
ALTER TABLE "company" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public full access company" ON "company" FOR ALL USING (true) WITH CHECK (true);

